import React, { useState } from 'react';
import Animation from './components/Animation';
import Controls from './components/Controls';

interface AnimationValues {
    outer: boolean;
    onlySuggestions: boolean;
    success: boolean;
    warning: boolean;
}

const App: React.FC = () => {
    const [values, setValues] = useState<AnimationValues>({
        outer: false,
        onlySuggestions: false,
        success: false,
        warning: false
    });

    return (
        <div>
            <h1>Rive Animation</h1>
            <Animation {...values} />
            <Controls onChange={setValues} />
        </div>
    );
};

export default App;
